"""Actual public research catalogue/metadata over HTTP; no benchmark file is loaded."""
import csv,io,json,os,shutil,threading,time
from functools import partial
from http.server import ThreadingHTTPServer,SimpleHTTPRequestHandler
from pathlib import Path
from playwright.sync_api import sync_playwright,expect
ROOT=Path(__file__).resolve().parents[1]
class Quiet(SimpleHTTPRequestHandler):
    def log_message(self,*_):pass

def main():
    manifest=json.loads((ROOT/'data/public/manifest.json').read_text());metadata=json.loads((ROOT/'data/public/boutique.json').read_text());total=str(manifest['counts']['records'])+' records';frame='overture-39fd34a0-9be1-4ac0-a46e-ebd53a1599ff';checks=0;report={}
    server=ThreadingHTTPServer(('127.0.0.1',0),partial(Quiet,directory=str(ROOT.parent)));threading.Thread(target=server.serve_forever,daemon=True).start();url=f'http://127.0.0.1:{server.server_port}/{ROOT.name}/'
    def passed(text):
        nonlocal checks;checks+=1;print('PASS '+text,flush=True)
    try:
        with sync_playwright() as pw:
            browser=pw.chromium.launch(executable_path=os.environ.get('CHROMIUM') or shutil.which('chromium'),headless=True,args=['--no-sandbox']);context=browser.new_context(viewport={'width':1440,'height':1000},accept_downloads=True);page=context.new_page();errors=[];requests=[];page.on('pageerror',lambda e:errors.append(str(e)));page.on('request',lambda r:requests.append(r.url))
            page.goto(url,wait_until='domcontentloaded');expect(page.locator('#count')).to_have_text(total,timeout=45000);assert not any('/boutique.json' in r for r in requests)
            passed('complete combined catalogue loads before any lazy boutique metadata request')
            start=time.monotonic();page.locator('[data-quick="boutique"]').click();expect(page.locator('#boutiqueFilters')).to_be_visible(timeout=30000);expect(page.locator('#count')).to_have_text(str(len(metadata['profiles']))+' records');report['boutique_first_open_seconds']=round(time.monotonic()-start,3)
            page.locator('#search').fill('Frame Machine');expect(page.locator('#count')).to_have_text('1 record');expect(page.locator('#list a[data-id="'+frame+'"]').first).to_be_visible();page.locator('#list a[data-id="'+frame+'"]').first.click();expect(page.locator('#profileTitle')).to_have_text('Frame Machine');expect(page.locator('.boutique-profile')).to_contain_text('realtime');expect(page.locator('.boutique-profile')).to_contain_text('External support need');expect(page.locator('#detailContent')).to_contain_text('Class C');expect(page.locator('.boutique-profile a[href="https://www.framemachine.tv/about-frame_machine/"]')).to_be_visible();page.locator('#close').click()
            passed('Frame Machine retains original Class C ID and exposes actual researched primary links, without inferred capture stages')
            page.locator('#search').fill('Floating Rock');page.wait_for_function('matches.length===1&&matches[0].name.startsWith("Floating Rock")');expect(page.locator('#count')).to_have_text('1 record');floating=page.evaluate('matches[0].id');assert page.evaluate('matches[0].lat===null&&matches[0].lng===null');page.locator('#list a[data-id="'+floating+'"]').click();expect(page.locator('#profileTitle')).to_contain_text('Floating Rock');expect(page.locator('#detailContent')).to_contain_text('Wellington');expect(page.locator('#detailContent')).to_contain_text('No source coordinates');expect(page.locator('.boutique-profile a[href="https://floating-rock.com/contact/"]')).to_be_visible();expect(page.locator('#detailContent')).to_contain_text('nzfc-annecy');page.locator('#close').click()
            passed('Floating Rock is a real research-visible NZFC-discovered reference with primary evidence, no fabricated pin or capability')
            page.locator('#search').fill('');page.locator('#boutiqueStatus').select_option('primary_claims_reviewed');page.locator('#boutiqueCinematics').check();page.locator('#boutiqueRealtime').check();page.locator('#boutiqueScore').select_option('40');page.wait_for_function('matches.length>0&&matches.every(r=>boutiqueData.profiles[r.id].signals.cinematics&&boutiqueData.profiles[r.id].signals.realtime)');assert page.evaluate('matches.some(r=>r.id==="'+frame+'")');report['filtered_search_compute_ms']=page.evaluate('MotionXPerformance.search_ms');page.locator('#boutiqueRegion').select_option('Asia');expect(page.locator('#count')).to_have_text('0 records');expect(page.locator('.empty-state')).to_be_visible();page.locator('#resetFilters').click();expect(page.locator('#count')).to_have_text(total)
            passed('AND capability/region/status/advisory score filters, useful empty state, and reset restore the whole atlas')
            page.locator('[data-quick="boutique"]').click();page.locator('#search').fill('Frame Machine');page.locator('[data-compare="'+frame+'"]').click();page.locator('#search').fill('Floating Rock');page.locator('[data-compare="'+floating+'"]').click();expect(page.locator('#profileTitle')).to_have_text('Compare research records');expect(page.locator('.comparison-record')).to_have_count(2);expect(page.locator('#detailContent')).to_contain_text('does not merge');page.locator('#close').click();page.locator('#resetFilters').click()
            passed('both golden businesses compare through actual catalogue profiles and keep separate source identities')
            proposed=json.loads((ROOT/'data/boutique/reports/proposals.json').read_text())['company_references'];licensed=next(r for r in proposed if r['license']=='CC-BY-4.0');page.locator('[data-quick="boutique"]').click();page.locator('#search').fill(licensed['name']);expect(page.locator('#list a[data-id="'+licensed['id']+'"]').first).to_be_visible()
            with page.expect_download(timeout=30000) as info:page.locator('#exportCsv').click()
            rows=list(csv.DictReader(io.StringIO(Path(info.value.path()).read_text(encoding='utf-8-sig'))));row=next(r for r in rows if r['id']==licensed['id']);assert row['evidence_class']=='C' and not row['lat'] and not row['capabilities'];assert row['advisory_service_alignment'];assert 'Creative Commons' in rows[0]['export_licences'];assert row['source_provenance'];report['licensed_export_records']=len(rows)
            passed('actual CC BY source export carries full licence, attribution and separate advisory columns; no verified capability is created')
            page.set_viewport_size({'width':390,'height':844});page.locator('#listTab').click();page.locator('#resetFilters').click();page.locator('[data-quick="boutique"]').focus();page.locator('[data-quick="boutique"]').press('Enter');expect(page.locator('#boutiqueFilters')).to_be_visible();page.locator('#boutiqueStatus').select_option('primary_claims_reviewed');assert page.evaluate('document.documentElement.scrollWidth<=innerWidth');page.screenshot(path='/tmp/motionx-v12-boutique-mobile.png',full_page=True);page.set_viewport_size({'width':1440,'height':1000});page.screenshot(path='/tmp/motionx-v12-boutique-desktop.png')
            passed('390px mobile layout and keyboard activation preserve map/list navigation without horizontal overflow')
            failed=context.new_page();failed.route('**/data/public/boutique.json.gz?*',lambda route:route.fulfill(status=503,body='Unavailable'));failed.goto(url,wait_until='domcontentloaded');expect(failed.locator('#count')).to_have_text(total,timeout=45000);failed.locator('[data-quick="boutique"]').click();expect(failed.locator('#dataStatus')).to_contain_text('Boutique evidence unavailable');expect(failed.locator('#count')).to_have_text(total);assert failed.locator('#boutiqueFilters').is_hidden();failed.unroute('**/data/public/boutique.json.gz?*');failed.locator('[data-quick="boutique"]').click();expect(failed.locator('#boutiqueFilters')).to_be_visible(timeout=30000);failed.close()
            passed('failed lazy metadata request leaves full directory usable and retry recovers without trusting partial results')
            assert not errors,errors;report.update(checks=checks,records=manifest['counts']['records'],boutique_metadata_bytes=(ROOT/'data/public/boutique.json').stat().st_size,boutique_metadata_gzip_bytes=(ROOT/'data/public/boutique.json.gz').stat().st_size,conditions='Local HTTP subdirectory, installed headless Chromium, 1440x1000 and 390x844, no CPU/network throttle. Not deployed Pages or a physical low-memory device. Benchmark JSON is never requested by the app.');Path('/tmp/motionx-v12-boutique-performance.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report),flush=True);browser.close()
    finally:server.shutdown();server.server_close()
    print(str(checks)+' boutique HTTP browser checks passed',flush=True)
if __name__=='__main__':main()
